import{_ as o,c as e,o as r,ag as s}from"./chunks/framework.B-XtCDNB.js";const a="/assets/1.0/images/data-transfer/createImport.png",i="/assets/1.0/images/data-transfer/saveImport.png",n="/assets/1.0/images/data-transfer/importNow.png",p="/assets/1.0/images/data-transfer/importOutput.png",y=JSON.parse('{"title":"Import","description":"","frontmatter":{},"headers":[],"relativePath":"1.0/data-transfer/import.md","filePath":"1.0/data-transfer/import.md","lastUpdated":1759498853000}'),l={name:"1.0/data-transfer/import.md"};function m(d,t,g,u,c,h){return r(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h1><p>Bulk import is a feature that allows users to import large quantities of data into a system quickly and efficiently. It simplifies the process and saves time by not having to add each piece of information one by one.</p><p>The feature works differently for each system and has a vast variety of use cases across many industries as well as <a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a>.</p><h3 id="steps-to-add-bulk-import-in-unopim" tabindex="-1">Steps to add Bulk Import in UnoPim <a class="header-anchor" href="#steps-to-add-bulk-import-in-unopim" aria-label="Permalink to &quot;Steps to add Bulk Import in UnoPim&quot;">​</a></h3><p><strong>Step 1:</strong> Go to the Admin panel of UnoPim click on <strong>Data Transfer &gt;&gt; Imports &gt;&gt; Create Import</strong>.</p><p><img src="'+a+'" alt="Create Import"></p><p><strong>Step 2:</strong> Under general configurations add the below fields:</p><ol><li><p><strong>Code -</strong> Enter the code of your Import process.</p></li><li><p><strong>Type -</strong> Kindly select the type i.e. (Products, Categories) which you want to import.</p></li><li><p><strong>File –</strong> Choose the file in your desired format <strong>(CSV, XLS, XLSX)</strong> and kindly make sure you have all the required fields in the file.</p></li><li><p><strong>Download Sample –</strong> You can also download the sample files of types (Products, Categories). Kindly make sure the file you are uploading is similar to this sample file.</p></li><li><p><strong>Image Directory Path –</strong> For product images files should be placed into <strong>/project-root/storage/app/import/product-images</strong> folder.</p></li><li><p><strong>Action –</strong> Kindly select from the settings configuration that you want to Create/Update or Delete the records.</p></li><li><p><strong>Validation Strategy –</strong> This unique feature allows you to Skip the Errors or to Stop on Errors while Importing the data.</p></li><li><p><strong>Allowed Errors –</strong> This feature allows you how much quantity of errors will get neglected while importing the data.</p></li><li><p><strong>Field Separator –</strong> This feature allows you to set the fields. For Example if you use <strong>&quot;,&quot;</strong> as a field separator then the data inside the file gets separated with this.</p></li></ol><p>Now, click on <strong>Save Import</strong> button.</p><p><img src="'+i+'" alt="Save Import"></p><p><strong>Step 3:</strong> Now click on <strong>Import Now</strong> button as shown in the below image.</p><p><img src="'+n+'" alt="Import Now"></p><p><strong>Step 4:</strong> Now click on <strong>Data Transfer &gt;&gt; Job Tracker</strong> where you see the status of your import process. After the status got completed then the import process is been done successfully.</p><p>Also you can run the below command in the root of your UnoPim.</p><p><strong>php artisan queue:listen</strong></p><p><img src="'+p+'" alt="Import Output"></p><p>So by the above steps you can easily create Import Data in UnoPim.</p>',17)])])}const _=o(l,[["render",m]]);export{y as __pageData,_ as default};
